"""Compact PRM serialization; never deduplicate text generated by a worker."""
from collections import Counter

from . import graphprm_core as core
from . import graphprm_sequence as seq
from .contract import model_record
from .graphprm_inputs import clean_result_text, delivered_result, escape_prm_field, check_rendered_markers

SERIALIZATION_VERSION = 'compact_v1'


def render_compact_sequence(record, tokenizer=None):
    record = model_record(record)
    subtasks, workers = seq.get_subtasks(record), seq.get_workers(record)
    nodes = list(subtasks) or list(workers)
    edges = seq.choose_edges(record, 'provided')
    order, cyclic = seq.topological_order(nodes, sorted(set(edges + seq.choose_edges(record, 'declared'))))
    if cyclic:
        order, provided_cycle = seq.topological_order(nodes, edges)
        if provided_cycle:
            raise ValueError('Cyclic provided-input snapshots require a separate execution-event schema')
    order = [node for node in order if node in workers]
    node_to_step = {node: i for i, node in enumerate(order, 1)}
    incoming = {node: [] for node in order}
    for source, target in edges:
        if target in incoming:
            incoming[target].append(source)

    safe = lambda value: escape_prm_field(value, tokenizer)
    parts, targets = [], []
    references = 0
    for index, node in enumerate(order, 1):
        worker = workers[node]
        subtask = subtasks.get(node) or worker.get('subtask') or {}
        dependencies = [dep for dep in sorted(set(incoming[node]), key=seq.node_sort_key)
                        if dep in node_to_step and node_to_step[dep] < index]
        phrase = seq.format_dependency_phrase(dependencies, node_to_step)
        if worker['dependency_context_status'] == 'unknown':
            phrase = 'provided context unknown'
        lines = [f'Step {index} [node {safe(node)}, {phrase}]:']
        instruction = safe(subtask.get('instruction') or worker.get('subtask_instruction') or '')
        if instruction:
            lines.append(f'Task: {instruction}')
        if dependencies:
            lines.append('Relevant previous results:')
            for dep in dependencies:
                supplied = worker['provided_inputs'][dep]
                # Reference only an exact snapshot already present earlier in this
                # same sequence. Changed/stale/contaminated snapshots stay literal.
                if supplied and supplied == delivered_result(workers[dep]):
                    value = f'[same delivered result as Step {node_to_step[dep]} above]'
                    references += 1
                else:
                    value = safe(supplied)
                lines.append(f'- Step {node_to_step[dep]} result: {value}')
        # Even if it copies an upstream result, this is the worker's own behavior.
        lines.append(f'Result: {safe(delivered_result(worker))}')
        parts.append('\n'.join(lines) + '\n<extra_0>')
        targets.append(dict(scope='worker', node_id=node, step_index=index,
                            is_final_worker=bool(worker.get('is_final_node'))))

    final = clean_result_text(record.get('trajectory', {}).get('final_answer', ''))
    final_node = core.effective_final_node_id(record)
    dependencies = [final_node] if final_node in node_to_step else []
    phrase = seq.format_dependency_phrase(dependencies, node_to_step)
    index = len(targets) + 1
    lines = [f'Step {index} [final answer, {phrase}]:', 'Task: Report the delivered final answer.']
    # The final aggregate is not an extra worker execution. Its contributing
    # worker result is already above; do not insert another dependency copy.
    if final and dependencies and final == delivered_result(workers[final_node]):
        lines.append(f'Result: [same delivered result as Step {node_to_step[final_node]} above]')
        references += 1
    else:
        lines.append(f'Result: {safe(final)}')
    parts.append('\n'.join(lines) + '\n<extra_0>')
    targets.append(dict(scope='final', node_id='f', step_index=index, is_final_worker=False))

    messages = [dict(role='system', content='Please reason step by step, and put your final answer within \\boxed{}.'),
                dict(role='user', content=safe(record.get('task', {}).get('prompt', ''))),
                dict(role='assistant', content='\n\n'.join(parts))]
    prompt = None
    if tokenizer is not None:
        try:
            prompt = tokenizer.apply_chat_template(messages, tokenize=False, add_generation_prompt=False)
        except Exception:
            pass
    if prompt is None:
        prompt = '\n\n'.join([messages[0]['content'], f"User: {messages[1]['content']}",
                              f"Assistant: {messages[2]['content']}"])
    check_rendered_markers(prompt, targets)
    branch, merge = Counter(s for s, _ in edges), Counter(t for _, t in edges)
    return dict(prompt=prompt, targets=targets, node_order=order, edges=edges, cyclic=cyclic,
                branch_node_count=sum(v > 1 for v in branch.values()),
                merge_node_count=sum(v > 1 for v in merge.values()),
                isolated_node_count=max(0, len(nodes) - len({n for e in edges for n in e})),
                serialization_version=SERIALIZATION_VERSION, result_references=references)
